  SELECT RAISE(ABORT, 'lifecycle_access_version_missing') WHERE NOT (EXISTS (SELECT 1 FROM "fanmark_licenses" WHERE "id" = NEW."license_id" AND "status" = 'expired' AND "lifecycle_claim_id" IS NOT NULL)) AND ((SELECT COUNT(*) FROM "fanmark_licenses" WHERE "id" = NEW."license_id") <> 1 OR (SELECT COUNT(*) FROM "fanmark_access_versions" AS av JOIN "fanmark_license_incarnations" AS ri ON ri."license_id" = av."license_id" AND ri."incarnation" = av."license_incarnation" WHERE av."license_id" = NEW."license_id") <> 1);
  SELECT RAISE(ABORT, 'lifecycle_access_generation_overflow') WHERE NOT (EXISTS (SELECT 1 FROM "fanmark_licenses" WHERE "id" = NEW."license_id" AND "status" = 'expired' AND "lifecycle_claim_id" IS NOT NULL)) AND NOT ((SELECT COUNT(*) FROM "fanmark_licenses" WHERE "id" = NEW."license_id") = 0 AND (SELECT COUNT(*) FROM "fanmark_access_versions" WHERE "license_id" = NEW."license_id") = 0) AND (SELECT "access_generation" FROM "fanmark_access_versions" WHERE "license_id" = NEW."license_id") >= 9007199254740991;
  UPDATE "fanmark_access_versions" SET "access_generation" = "access_generation" + 1, "updated_at" = strftime('%Y-%m-%dT%H:%M:%f000Z', 'now') WHERE "license_id" = NEW."license_id" AND NOT (EXISTS (SELECT 1 FROM "fanmark_licenses" WHERE "id" = NEW."license_id" AND "status" = 'expired' AND "lifecycle_claim_id" IS NOT NULL));
  SELECT RAISE(ABORT, 'lifecycle_access_version_missing') WHERE NOT (EXISTS (SELECT 1 FROM "fanmark_licenses" WHERE "id" = NEW."license_id" AND "status" = 'expired' AND "lifecycle_claim_id" IS NOT NULL)) AND NOT ((SELECT COUNT(*) FROM "fanmark_licenses" WHERE "id" = NEW."license_id") = 0 AND (SELECT COUNT(*) FROM "fanmark_access_versions" WHERE "license_id" = NEW."license_id") = 0) AND changes() <> 1;
END;
